mapper.select:
select u.user_id, u.dept_id, u.nick_name, u.user_name, u.email, u.avatar, u.phonenumber, u.sex, u.status, u.del_flag, u.login_ip, u.login_date, u.create_by, u.create_time, u.remark, d.dept_name, d.leader from sys_user u left join sys_dept d on u.dept_id = d.dept_id where u.del_flag = '0'
AND u.user_id = #{userId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.status = #{status}
AND u.phonenumber like concat('%', #{phonenumber}, '%')
AND date_format(u.create_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')
AND date_format(u.create_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')
AND (u.dept_id = #{deptId} OR u.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE find_in_set(#{deptId}, ancestors) ))
${params.dataScope}

select u.user_id, u.dept_id, u.user_name, u.nick_name, u.phonenumber, d.dept_name, d.dept_type, p.dept_id as parent_id, p.dept_name as parent_name from sys_user u join sys_dept d on d.dept_id = u.dept_id and d.del_flag = '0' left join sys_dept p on p.dept_id = d.parent_id and p.del_flag = '0' where u.del_flag = '0' and
and d.dept_id = #{params.classId}
and u.status = '0' and coalesce(d.dept_type, '') != 'CLASS' and (d.dept_id = #{params.schoolId} or find_in_set(#{params.schoolId}, d.ancestors))
and (d.dept_id = #{deptId} or find_in_set(#{deptId}, d.ancestors))
and (u.user_name like concat('%', #{userName}, '%') or u.nick_name like concat('%', #{userName}, '%') or u.phonenumber like concat('%', #{userName}, '%'))
and u.user_name regexp '^[0-9]{5,}$' and left(u.user_name, 4) = #{params.grade}
and u.user_id in #{id}
and u.user_name in #{account}
${params.dataScope} order by u.user_id desc

select distinct u.user_id, u.dept_id, u.user_name, u.nick_name, u.email, u.phonenumber, u.status, u.create_time from sys_user u left join sys_dept d on u.dept_id = d.dept_id left join sys_user_role ur on u.user_id = ur.user_id left join sys_role r on r.role_id = ur.role_id where u.del_flag = '0' and r.role_id = #{roleId}
AND u.user_name like concat('%', #{userName}, '%')
AND u.phonenumber like concat('%', #{phonenumber}, '%')
${params.dataScope}

mapper.update:
update sys_user
dept_id = #{deptId}, nick_name = #{nickName}, email = #{email}, phonenumber = #{phonenumber}, sex = #{sex}, avatar = #{avatar}, password = #{password}, status = #{status}, login_ip = #{loginIp}, login_date = #{loginDate}, update_by = #{updateBy}, remark = #{remark}, update_time = sysdate()
where user_id = #{userId}
